  7801  PackLinuxElf64::elf_get_offset_from_address(upx_uint64_t addr) const
  7802  {
  7803      Elf64_Phdr const *phdr = phdri;
  7804      int j = e_phnum;
  7805      for (; --j>=0; ++phdr) if (PT_LOAD64 == get_te32(&phdr->p_type)) {
  7806          upx_uint64_t const t = addr - get_te64(&phdr->p_vaddr);
  7807          if (t < get_te64(&phdr->p_filesz)) {
  7808              upx_uint64_t const p_offset = get_te64(&phdr->p_offset);
  7809              if ((u64_t)file_size <= p_offset) { // FIXME: weak
  7810                  char msg[40]; snprintf(msg, sizeof(msg),
  7811                      "bad Elf64_Phdr[%d].p_offset %#lx",
  7812                      -1+ e_phnum - j, (long unsigned)p_offset);
  7813                  throwCantPack(msg);
  7814              }
  7815              return t + p_offset;
  7816          }
  7817      }
  7818      return 0;
  7819  }
