  7821  u64_t  // returns .p_offset
  7822  PackLinuxElf64::check_pt_load(Elf64_Phdr const *const phdr)
  7823  {
  7824      u64_t filesz = get_te64(&phdr->p_filesz);
  7825      u64_t offset = get_te64(&phdr->p_offset), offend = filesz + offset;
  7826      u64_t vaddr  = get_te64(&phdr->p_vaddr);
  7827      u64_t paddr  = get_te64(&phdr->p_paddr);
  7828      u64_t align  = get_te64(&phdr->p_align);
  7829
  7830      if ((-1+ align) & (paddr ^ vaddr)
  7831      ||  (u64_t)file_size <= (u64_t)offset
  7832      ||  (u64_t)file_size <  (u64_t)offend
  7833      ||  (u64_t)file_size <  (u64_t)filesz) {
  7834          char msg[50]; snprintf(msg, sizeof(msg), "bad PT_LOAD phdr[%u]",
  7835              (unsigned)(phdr - phdri));
  7836          throwCantPack(msg);
  7837      }
  7838      return offset;
  7839  }
